<?php $lines=cart_lines();$subtotal=cart_subtotal($lines);?><main id="main" class="content-page"><div class="page-heading"><p class="eyebrow">LE VESTIAIRE SE COMPOSE</p><h1>Votre sélection.</h1></div><?php if(!$lines):?><div class="empty-state"><p>Votre histoire reste à composer.</p><a class="button" href="<?=e(route('shop'))?>">Explorer le vestiaire</a></div><?php else:?><div class="checkout-layout"><div class="cart-lines"><?php foreach($lines as $l):?><article class="cart-line"><a href="<?=e(route('product',['slug'=>$l['slug']]))?>"><img src="<?=e(media_url('product-'.sprintf('%02d',$l['product_id']).'-variant-'.sprintf('%02d',$l['color_order'])))?>" alt="<?=e($l['name'].' '.$l['color_name'])?>" width="160" height="160"></a><div><h2><a href="<?=e(route('product',['slug'=>$l['slug']]))?>"><?=e($l['name'])?></a></h2><p><?=e($l['color_name'])?> · <?=e($l['size_label'])?></p><p><?=e(money($l['price_millimes']===null?null:(int)$l['price_millimes']))?></p><form method="post" action="<?=e(url('actions/cart.php'))?>"><?=csrf_input()?><input type="hidden" name="operation" value="update"><input type="hidden" name="variant_id" value="<?=$l['id']?>"><label>Quantité <input class="cart-qty" name="quantity" type="number" min="0" max="<?=min(config('max_cart_quantity'),(int)$l['stock'])?>" value="<?=$l['quantity']?>"></label><button type="submit" class="text-button">Mettre à jour</button><button name="remove" value="1" formnovalidate class="text-button" type="submit">Retirer</button></form></div><strong><?=e(money((int)$l['price_millimes']*$l['quantity']))?></strong></article><?php endforeach;?></div><aside class="cart-summary"><h2>Votre commande</h2><div><span>Sous-total</span><strong><?=e(money($subtotal))?></strong></div><p>Les frais de livraison sont indiqués avant validation.</p><a class="button" href="<?=e(route('checkout'))?>">Continuer la commande →</a><a href="<?=e(route('shop'))?>">Poursuivre la découverte</a></aside></div><?php endif;?></main>